    /** 按「省·市」或城市名查经度，返回第一个匹配 */
    fun lonOf(province: String, city: String): Double? {
        val p = PROVINCES.firstOrNull { it.name == province } ?: PROVINCES.firstOrNull { it.name.contains(province) }
        p?.cities?.firstOrNull { it.name == city }?.let { return it.lon }
        return PROVINCES.firstOrNull { pr -> pr.cities.any { it.name == city } }?.cities?.firstOrNull { it.name == city }?.lon
    }
